<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'پشتیبانی'});const{api}=useShopApi();const{data,refresh}=await useAsyncData('my-tickets',()=>api<any>('/profile/tickets'));const creating=ref(false),form=reactive({subject:'',department:'support',priority:'normal',body:''});const labels:any={open:'باز',customer_reply:'پاسخ شما',answered:'پاسخ پشتیبانی',closed:'بسته'};async function create(){await api('/profile/tickets',{method:'POST',body:form});Object.assign(form,{subject:'',department:'support',priority:'normal',body:''});creating.value=false;await refresh()}</script>
<template><div class="mx-auto max-w-5xl px-4 py-10"><div class="flex items-center justify-between"><div><p class="text-sm text-slate-400">حساب کاربری</p><h1 class="mt-1 text-2xl font-black">تیکت‌های پشتیبانی</h1></div><button class="rounded-xl bg-brand-700 px-5 py-3 text-sm font-bold text-white" @click="creating=!creating">تیکت جدید</button></div><form v-if="creating" class="mt-6 rounded-2xl border bg-white p-6" @submit.prevent="create"><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">موضوع<input v-model="form.subject" required class="mt-2 h-11 w-full rounded-xl border px-3"></label><label class="text-sm font-bold">بخش<select v-model="form.department" class="mt-2 h-11 w-full rounded-xl border px-3"><option value="support">پشتیبانی عمومی</option><option value="orders">سفارش‌ها</option><option value="payment">پرداخت</option><option value="returns">مرجوعی</option></select></label></div><textarea v-model="form.body" required minlength="5" rows="4" class="mt-4 w-full rounded-xl border p-3" placeholder="پیام شما…"/><button class="mt-3 rounded-xl bg-slate-900 px-5 py-3 font-bold text-white">ارسال تیکت</button></form><div class="mt-6 space-y-3"><NuxtLink v-for="t in data?.data" :key="t.id" :to="`/profile/tickets/${t.id}`" class="flex items-center justify-between rounded-2xl border bg-white p-5"><div><b>{{t.subject}}</b><p class="mt-2 text-xs text-slate-400">{{t.number}} • {{new Date(t.last_message_at).toLocaleString('fa-IR')}}</p></div><span class="rounded-lg bg-brand-50 px-3 py-1 text-xs font-bold text-brand-700">{{labels[t.status]||t.status}}</span></NuxtLink><div v-if="!data?.data?.length" class="rounded-2xl border border-dashed bg-white p-12 text-center text-slate-400">هنوز تیکتی ثبت نکرده‌اید.</div></div></div></template>
